"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2692],{96422:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Builds a queue. Alias of [Matchmaker.new], where the configuration is\\ndocumented.","params":[{"name":"config","desc":"","lua_type":"MatchmakerConfig"}],"returns":[{"desc":"","lua_type":"Matchmaker"}],"function_type":"static","source":{"line":191,"path":"src/init.luau"}}],"properties":[],"types":[],"name":"Muster","desc":"Package entry point.\\n\\nMuster forms matches across servers: it shards a queue into lanes, elects a\\nworker per lane, groups tickets by size and rating, and delivers the result\\nto every server holding a matched player. It does not teleport players,\\nreserve servers, or compute ratings \u2014 those attach through the `finalize`\\nhook and the rating you supply.\\n\\n```lua\\nlocal Muster = require(ReplicatedStorage.Packages.Muster)\\n\\nlocal duels = Muster.new({ name = \\"duels\\", size = 2 })\\n\\nduels.matched:connect(function(match)\\n\\tprint(`{match.size} players matched as {match.matchId}`)\\nend)\\n\\nduels:enqueue(player.UserId)\\n```\\n\\nStart at [Matchmaker]. [Party] covers cross-server parties, [Result] the\\nerror convention, and [Types] every exported type.","source":{"line":29,"path":"src/init.luau"}}')}}]);